get.description:
Liveness + readiness probe.

Response shape::

    {
      "data": {
        "database": "ok" | "error",
        "redis":    "ok" | "error",
        "celery":   "ok" | "fail"
      },
      "meta": {
        "request_id":   "...",
        "data_status":  "fresh" | "partial",
        "as_of":        "<ISO-8601>",
        "cached_layer": "provider"
      }
    }
